pug:
table.row.card(role='presentation' align='center' width='100%')
    tr
        td.card-cell
            h1.card-title {{ title }}
            p.card-text {{ body }}

styl:
.row.card { background: {{ card_bg }}; border-radius: {{ card_radius }}px; border-collapse: separate; width: 100%; }
.row.card td.card-cell { padding: {{ card_padding }}; text-align: left; }
.row.card h1.card-title { font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 700; font-size: {{ title_size }}px; line-height: 1.18; color: {{ title_color }}; margin: 0 0 18px; padding: 0; }
.row.card p.card-text { font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 400; font-size: {{ body_size }}px; line-height: 1.55; color: {{ body_color }}; margin: 0 0 12px; padding: 0; }
